import type { BlogPost } from './types';
import type { ResearchPost } from './types';

export const november07BlogPosts: readonly BlogPost[] = [{"slug":"build-a-client-billing-guideline-change-log","title":"Build a client billing guideline change log","description":"A working change log that shows which client billing rule changed, when it took effect, and which review fields the billing team must update.","category":"Billing guidelines","readTime":"8 min read","thumbnail":"/thumbnails/november-07/build-a-client-billing-guideline-change-log.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/write-a-time-entry-narrative-standard-clients-can-audit","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"Why a change log belongs beside the summary","paragraphs":["A client billing guideline changes more often than most billing teams redocument it. A rate note arrives by email, an outside counsel policy is reissued, and one paragraph on travel time quietly shifts the review standard. Without a change log, reviewers keep applying the old rule until a rejection or a partner correction exposes the gap. The log makes the change visible before it reaches a live prebill.","A change log is not a copy of the client email and it is not a second guideline summary. It is a dated record of what changed, where the change applies, and which checklist field now needs a different answer. Keep it short enough that a reviewer can scan the current cycle in under a minute. Each entry should stand alone without requiring the reader to open a long thread."]},{"heading":"Record the source, version, and effective date","paragraphs":["Every entry begins with the source document, its version label, and the date the client says the rule takes effect. Record who received the document and where the controlled copy is stored. If the client sent a redline instead of a clean version, note that the redline is the source and that the clean copy is pending. Those details matter when two reviewers disagree about which rule was live on a given billing date.","The effective date is not always the date the email arrived. A client may issue a policy in June that applies to invoices for work performed from July onward. Write both dates when they differ, and state whether matters already open are covered. Reviewers need that distinction to avoid reprocessing closed periods or missing work in progress."]},{"heading":"Separate substantive changes from formatting edits","paragraphs":["A reissued guideline usually contains both real rule changes and cosmetic edits. Mark substantive changes separately so the review team does not retrain on a changed heading or a new page number. A substantive change alters what may be billed, who must approve it, or what evidence must accompany the line. Formatting edits can be noted and archived without touching the checklist.","Use three labels: new rule, changed rule, and withdrawn rule. The withdrawn label matters because an assistant may still be following a restriction the client removed. Record what replaces the withdrawn text or state clearly that the field no longer applies. Reviewers should never have to infer a withdrawal from the absence of a sentence."]},{"heading":"Map each change to the checklist field it affects","paragraphs":["Link every substantive change to the specific checklist item, system field, or escalation trigger it touches. A change to block billing rules might affect the narrative check, while a change to staffing rules might affect the timekeeper field. Write the field name exactly as it appears in the billing system. That precision turns a policy note into an operating instruction.","When a change affects no current checklist field, say so and name the owner who will decide whether a new check is needed. Not every client preference deserves a new control, and adding fields without a clear review purpose creates clutter. The log should show the decision, not just the policy language. A short note about why no change was made is useful evidence at the next review."]},{"heading":"Notify the reviewers who apply the rule","paragraphs":["Send the change notice to the people who actually review the affected queue, not only to the billing partner or client relationship owner. Include the old rule, the new rule, and one worked example of the difference. A message that forwards a thirty page guideline without a summary will be read unevenly. The log entry can serve as the body of the notice when it is written clearly.","Ask each reviewer to confirm receipt and to state one record they will recheck under the new rule. Confirmation is not bureaucracy when the change affects money or client trust. It gives the queue owner a way to see who has acknowledged the update before the next prebill release. Keep the confirmations with the log entry so the record is complete."]},{"heading":"Test the change on a small live sample","paragraphs":["Apply the new rule to a small sample of current prebills before the next full cycle. Choose records that sit close to the changed boundary so the test actually exercises the new language. Have the reviewer document the status and the evidence used for each sample line. Then compare the results with the queue owner or billing partner.","A sample can reveal that the new rule conflicts with the billing system or with another client instruction. Resolve that conflict before the rule reaches the broader queue. Update the change log with the test date and any clarification that came out of it. The tested interpretation becomes the version reviewers apply until the client says otherwise."]},{"heading":"Keep superseded versions reachable","paragraphs":["Archive the prior summary and checklist version rather than overwriting them in place. Matters billed under an earlier agreement may still require the older rule, and a reviewer may need to explain a historical decision. Name archived files with the version and effective period so the correct copy is easy to find. Access should be read only for reviewers who do not maintain the archive.","Link each change log entry to the version it supersedes. That link lets a reviewer move from a current rule to the exact prior language in one step. Avoid storing old versions only in email, because search results do not prove which attachment was official. A controlled archive is part of the evidence trail, not an administrative extra."]},{"heading":"Review the log at every billing cycle","paragraphs":["At the close of each billing cycle, check whether any client guideline change arrived but never reached the log. Ask the billing partner, the client relationship owner, and the accounts team for updates they received directly. A log that only captures messages sent to one inbox will miss changes routed through other channels. The review closes that gap before it becomes a billing dispute.","Use the same review to retire entries that no longer need active attention. Move closed changes into an archive view while keeping them searchable by client, matter type, and date. Report the number of open changes and the fields still awaiting a checklist update. A short monthly status note keeps the log from becoming a museum of old policy."]}],"faq":[{"q":"Who should maintain the change log?","a":"The billing manager or prebill queue owner should maintain it, with the client relationship owner confirming source documents. A billing assistant can prepare entries and gather evidence, but an accountable owner should approve substantive changes. Name one backup so the log does not stall during leave."},{"q":"What belongs in the first entry?","a":"Start with the client, matter scope, source document, version, effective date, the rule that changed, and the checklist field affected. Add one worked example and the name of the reviewer who confirmed the change. Link the controlled copy and the prior version."},{"q":"How is the log different from the guideline summary?","a":"The summary states the current operating rules in one place. The log records how those rules changed over time and which fields moved. Reviewers use the summary for daily work and the log to understand a shift or verify a historical decision."}],"publishedAt":"2026-11-07"},{"slug":"write-a-time-entry-narrative-standard-clients-can-audit","title":"Write a time-entry narrative standard clients can audit","description":"A practical standard for time-entry narratives that names the task, the matter, the outcome, and the evidence a client reviewer needs to approve the line.","category":"Time capture","readTime":"9 min read","thumbnail":"/thumbnails/november-07/write-a-time-entry-narrative-standard-clients-can-audit.webp","internalService":"/services/time-entry-review-support","internalSibling":"/blog/design-a-prebill-hold-queue-with-named-release-reasons","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Start with the client's actual narrative requirement","paragraphs":["Begin with the language the client uses in its outside counsel guidelines, not with the firm's internal habit. Some clients require task, activity, and result in separate fields, while others ask for a single narrative that stands alone. Read the current guideline and note every explicit narrative rule before drafting a standard. A standard that ignores the client's own wording will produce avoidable revisions.","Where the guideline is silent, look at the client's prior invoice edits for evidence of what its reviewers expect. Group the comments into recurring themes such as vague task descriptions, missing matter context, or unexplained time blocks. Those themes are stronger evidence than a general preference for detail. Use them to draft rules the client has effectively already stated through its review behavior."]},{"heading":"Define the components of a complete entry","paragraphs":["A complete entry answers four questions: what was done, for which matter or issue, what it produced, and why the time is reasonable. The narrative should name the document reviewed, the motion drafted, or the call conducted rather than saying work was performed. It should connect the task to the matter phase so a reviewer can see why the work was necessary. It should also make the time increment understandable without a separate explanation.","Write the standard as a short template with required and optional elements. Required elements might include the task, the subject, and the deliverable, while optional elements might include the person consulted or the next step. Give one positive example and one weak example for each element. A template with examples is easier to apply under queue pressure than a page of abstract guidance."]},{"heading":"Show the difference between task and outcome","paragraphs":["A task describes the activity, while an outcome describes what the activity changed or produced. Reviewing a lease is a task, but identifying three assignment clauses for the client's financing is an outcome. Both belong in a strong narrative because the client is paying for the work and for the judgment it enabled. Teach the distinction with paired examples drawn from the firm's own practice.","Avoid turning every entry into a long memo. The standard should ask for the outcome that matters to the matter, not a summary of everything the timekeeper knows. One precise clause can be more useful than a paragraph of background. Reviewers should be able to see the value of the work in the first sentence and the supporting detail in the second."]},{"heading":"Set rules for block and multiple-task entries","paragraphs":["Block entries hide the relationship between time and task, so the standard should either prohibit them or require a breakdown. If the client permits a block entry for a single continuous activity, define what counts as continuous and how the narrative should describe the sequence. If several tasks were performed, ask for separate lines or an itemized narrative with time allocated to each. Ambiguity here is a common source of write-downs.","Give timekeepers a simple test before combining tasks. If a reviewer would need different evidence to approve each part of the work, the entry should be split. If the parts share the same document, purpose, and outcome, a single entry may be appropriate with a clear sequence. Apply the same test across the team so two timekeepers do not treat similar work differently."]},{"heading":"Handle confidential and privileged detail","paragraphs":["A narrative must give the client enough context to review the charge without exposing privileged content to the wrong reader. Describe the category of advice and the business purpose rather than quoting legal analysis. Refer to a memo by its subject and date instead of restating its conclusion. The client reviewer usually needs to recognize the work, not read the legal reasoning again.","Set a rule for when a timekeeper should consult the supervising attorney before writing a sensitive narrative. Examples include matters under seal, internal investigations, and communications with regulators. The standard should name the approver and the alternative wording to use while approval is pending. Confidentiality is a reason to phrase carefully, not a reason to leave the entry vague."]},{"heading":"Test narratives against a client review sample","paragraphs":["Pull a recent sample of approved and rejected narratives from the same client and score them against the new standard. Record which component was missing in each rejected line and which element made each approved line clear. If the standard cannot explain the client's decisions, revise the standard before training the team. The sample is the closest available evidence of the client's real expectations.","Include entries from more than one timekeeper and more than one matter type. A standard that works only for litigation associates may fail for regulatory or transactional work. Compare the scores across groups and look for patterns in the misses. Those patterns tell you where the template needs a specific example rather than another general instruction."]},{"heading":"Coach deviations with specific examples","paragraphs":["When a reviewer finds a weak narrative, respond with the exact element that was missing and a rewritten version of the same entry. General feedback such as be more specific rarely changes the next entry. Showing the original and the revision side by side makes the standard concrete. Keep the example in the coaching file so the next reviewer can use it too.","Track whether the same timekeeper repeats the same defect after coaching. A repeated miss may indicate a misunderstanding of the matter, a missing source document, or a template that does not fit the work. Address the cause rather than escalating the tone of the feedback. Coaching should improve the next entry, not merely document the last one."]},{"heading":"Refresh the standard when guidelines change","paragraphs":["Connect the narrative standard to the client billing guideline change log so a new requirement triggers a review. Update the template, the examples, and the training note in the same cycle. Tell reviewers which entries need a second look under the revised rule. A standard that drifts behind the guideline will produce confident but wrong narratives.","Review the standard at least annually even when no client change arrives. New matter types, new timekeepers, and new billing systems can expose gaps that were invisible a year earlier. Ask the client-facing team which comments keep recurring and add one improvement each cycle. The standard should be a living operating document, not a one-time writing exercise."]}],"faq":[{"q":"How long should a time-entry narrative be?","a":"Long enough to name the task, the subject, the outcome, and the reason for the time, and short enough that a reviewer can scan it. Most entries need one or two focused sentences. Length is not a substitute for specificity, and padding makes the billable value harder to see."},{"q":"Should every entry include an outcome?","a":"Include an outcome when the work produced a document, decision, or next step the client would recognize. Some routine tasks may only need a precise activity and subject. The standard should say which matter types require the fuller form so timekeepers are not guessing."},{"q":"How should a firm handle client-specific formats?","a":"Keep one core standard and add a client appendix for required fields or phrasing. The appendix should cite the guideline section and give a worked example. Reviewers then apply the core rule plus the client variation without maintaining a separate standard for every client."}],"publishedAt":"2026-11-07"},{"slug":"design-a-prebill-hold-queue-with-named-release-reasons","title":"Design a prebill hold queue with named release reasons","description":"How to organize prebill holds by release authority, required evidence, and age so nothing waits in an unnamed queue or releases without a decision.","category":"Prebill workflow","readTime":"8 min read","thumbnail":"/thumbnails/november-07/design-a-prebill-hold-queue-with-named-release-reasons.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/use-a-five-field-test-before-reopening-a-closed-invoice","source":{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},"sections":[{"heading":"A hold without a reason is just a delay","paragraphs":["A prebill hold tells the team that a record is not ready to release, but the label alone does not say what must happen next. When holds are recorded as pending review or waiting on partner, the queue owner cannot tell whether the work is blocked, forgotten, or already answered. Naming the release reason turns a passive wait into a specific decision. It also makes the age of each hold meaningful.","The queue should distinguish a hold from a draft in progress. A draft still needs preparation, while a hold is complete enough to review but cannot be released until a defined condition is met. Mixing the two inflates the hold count and hides the records that truly need intervention. Separate the states before designing the reason list."]},{"heading":"Name the categories of release authority","paragraphs":["Group release reasons by the person or role that can clear them. Common categories include partner approval, billing manager correction, client clarification, rate confirmation, and matter record completion. Each category should have one accountable owner and one backup. When a reason has no owner, it becomes a permanent hold with a polite name. Record the backup owner in the same list so a leave does not create a new unnamed hold.","Keep the list short enough to use consistently. Six to ten categories usually cover a legal billing queue, and every category should describe a decision rather than a department. For example, use client approval for a specific charge instead of client side. The label should tell a reviewer what evidence will release the record. Test the list against a month of real holds and merge any label that two reviewers used for the same decision."]},{"heading":"Attach the evidence each hold requires","paragraphs":["For every reason, write the evidence that must be attached before the hold can clear. A partner approval might require a dated email or an approval note in the billing system, while a rate confirmation might require the current rate card and the client's written acceptance. Evidence should be stored where the reviewer can see it without searching a personal inbox. A hold that clears on memory alone is not a controlled release.","Specify the minimum content of the evidence, not just its format. An email that says approved is weaker than an email that identifies the matter, the charge, and the amount. The required fields should match the fields the billing system will carry into the invoice. Reviewers should reject incomplete evidence at the point of attachment rather than weeks later."]},{"heading":"Set an age threshold for every hold type","paragraphs":["Different holds deserve different clocks. A rate confirmation may need same-day attention before a deadline, while a client clarification may reasonably take several business days. Set a target age for each reason and a point at which the hold escalates. The target should reflect the consequence of delay, not an arbitrary service level copied from another queue.","Record the hold start date and the last action date separately. A record that was touched yesterday but has waited three weeks is still old, and a recent hold with no action is also at risk. The queue report should show both ages so the owner can see whether activity is real progress or just a status change. Use the older of the two dates when the queue report cannot show both."]},{"heading":"Route holds to one accountable queue","paragraphs":["Keep all holds in one visible queue even when different people own the release decision. Separate spreadsheets for partner holds, client holds, and rate holds create blind spots and duplicate follow-up. A single queue with an owner field lets the billing manager see the whole backlog. It also prevents a record from being marked cleared in one list while remaining open in another.","The queue owner should review the full list at a fixed time each day and assign the next action for anything that has moved past its target. Ownership of the queue does not mean ownership of every decision. It means someone is responsible for seeing that each hold reaches the right decision maker and does not drift. That distinction keeps the review cadence from becoming a reminder schedule with no decision behind it."]},{"heading":"Report holds by age and release reason","paragraphs":["A count of open holds is not enough to manage the queue. Report the number by reason, the median and oldest age, and the share that have passed their target. That view shows whether the problem is a slow approver, an unclear client rule, or a category that should not be a hold at all. Trends matter more than a single day's total.","Include the number of holds cleared in the period and the average time to clear. Compare the mix with the prior period so a rise in one reason is visible. If partner approval holds are growing, the fix may be a standing approval meeting rather than more reminders. The report should point to a decision, not just describe the backlog."]},{"heading":"Review the hold taxonomy each month","paragraphs":["Some hold reasons become obsolete when a process changes, and new reasons appear when a client adds a requirement. Review the list monthly with the billing manager and a reviewer who works the queue. Ask which reasons were used rarely, which were used for more than one kind of decision, and which caused confusion. Merge or retire the categories that no longer earn their place.","When a reason is retired, keep the historical records intact so old holds can still be explained. Update the queue template and the reviewer guide in the same change. A taxonomy that grows without pruning becomes a second language that only the original team understands. Maintenance is part of the control. Keep the retired labels in a read-only reference so a reviewer can still interpret an older queue export."]},{"heading":"Close holds with a documented decision","paragraphs":["A hold should close with a record of who decided, what they decided, and which evidence supported the decision. If the answer was to remove a charge, note the amount and the client reference. If the answer was to release the charge, note the approval and any condition attached. The closure record should let a later reviewer reconstruct the choice without contacting the original owner.","Reopen a closed hold only through the same reason list, not by editing the old record silently. A reopened hold gets a new start date and a link to the prior decision. That history is useful when the same charge is questioned again. Clean closure is what makes the queue trustworthy over time. Record the reopening reason in the same log so the queue can distinguish a new issue from a repeated one."]}],"faq":[{"q":"What is the difference between a hold and a draft?","a":"A draft still needs preparation before anyone can review it. A hold is ready for a decision but cannot be released until a named condition is met. Track them separately so the hold queue reflects real blockers rather than unfinished work."},{"q":"Who should own the hold queue?","a":"The prebill manager or a designated queue owner should own the list and its daily review. Decision authority stays with the named approver for each reason. The queue owner makes sure every hold reaches that approver and records the outcome."},{"q":"How often should hold reasons be reviewed?","a":"Review the taxonomy monthly during the first quarter and quarterly after it stabilizes. Also review it whenever a client changes its guidelines or a new billing system field is introduced. Retire reasons that no longer describe a real decision."}],"publishedAt":"2026-11-07"},{"slug":"run-a-daily-e-billing-status-reconciliation","title":"Run a daily e-billing status reconciliation","description":"A daily reconciliation routine that compares the vendor portal, the billing system, and the internal status record before a stale submission becomes a missed deadline.","category":"E-billing","readTime":"8 min read","thumbnail":"/thumbnails/november-07/run-a-daily-e-billing-status-reconciliation.webp","internalService":"/services/e-billing-support","internalSibling":"/blog/create-a-matter-billing-contact-sheet-for-faster-escalation","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"Why a weekly status check is too slow","paragraphs":["An e-billing submission can move through acceptance, rejection, adjustment, and payment within a few business days. A weekly status check may find a rejection after the correction window has already narrowed. It may also show a paid invoice as pending because the internal record was never updated. Daily reconciliation keeps the team close enough to the portal to act while the issue is still small.","Daily does not mean reviewing every invoice in full. It means checking the records that changed since the last review and confirming that the internal status matches the portal. A short, consistent check is more useful than an occasional deep audit. The routine should be simple enough to survive a busy Monday. Reserve a longer review for month-end and for vendors that batch their status updates."]},{"heading":"Pick the fields that define a status","paragraphs":["Define status using a small set of fields that both systems can support. Useful fields include submission date, current portal status, last portal update, rejection reason code, expected payment date, and the internal owner. If a field exists in the portal but not in the billing system, record it in a controlled reconciliation sheet. The goal is a shared definition, not a perfect data model.","Write down what each status means in plain language. Accepted should mean the vendor received the invoice without a rejection, not that the client approved payment. Paid should mean funds were applied, not that the invoice was submitted. Ambiguous labels cause more reconciliation errors than missing fields. Post the definitions beside the reconciliation sheet so a new reviewer applies the same meaning."]},{"heading":"Compare the portal against the internal record","paragraphs":["For each changed invoice, open the portal record and the internal billing record side by side. Compare the status, the amount, the submission date, and the rejection reason if one exists. Note any field that differs and decide which source is authoritative for that field. The portal usually controls the submission state, while the billing system controls the firm's internal workflow.","Do not overwrite the internal record until the difference is understood. A portal status may lag because the vendor has not processed a batch, or the internal record may be wrong because someone updated the wrong invoice. Record the discrepancy first, then correct the source that is actually incorrect. A silent overwrite destroys the evidence needed to fix the process."]},{"heading":"Triage mismatches by consequence","paragraphs":["Not every mismatch needs the same response. A rejected invoice with a short correction window needs immediate action, while a cosmetic status label can wait for the next cleanup. Rank mismatches by the risk of lost revenue, missed deadline, client confusion, or duplicate submission. The ranking tells the reviewer what to work first when the queue is long.","Use a small set of action labels: correct now, confirm with vendor, update internal record, and monitor. Each label should have a target response time and a named owner. A mismatch that cannot be resolved the same day should move to a follow-up list with a next action date. The label keeps the queue honest about what is actually pending."]},{"heading":"Assign follow-up with a named owner","paragraphs":["Every open mismatch needs a person, not a team mailbox. The owner may be the billing assistant, the e-billing specialist, or the accounts receivable contact, depending on the issue. Record the owner beside the next action and the date it is due. When ownership is unclear, the queue owner assigns it before the review ends.","Follow-up should reference the invoice, the portal confirmation number, and the specific question. A message that says please check status gives the vendor nothing to resolve. A message that names the rejection code and the corrected line gets a faster answer. Good follow-up also creates a record that can be used if the issue escalates."]},{"heading":"Log the reconciliation result each day","paragraphs":["Keep a daily log with the number of records reviewed, the number changed, the mismatches found, and the actions opened. The log does not need narrative for every invoice, but it should show the shape of the day. Patterns become visible when the same rejection code or the same vendor delay appears across several entries. The log is also evidence that the check happened.","Store the log where the billing manager can review it without asking for access. A shared sheet with a simple date column is enough for a small team. If the team uses a ticketing system, a saved filter can serve the same purpose. The important feature is consistency, not sophistication. Review the log weekly for gaps in dates or owners and correct the template before the next cycle."]},{"heading":"Escalate stale statuses before they age","paragraphs":["Set an age limit for each status and escalate when a record exceeds it. A submitted invoice with no portal response after several business days may need a vendor call. A rejected invoice with no correction after the stated window may need a billing manager decision. The age limit should reflect the vendor's actual process and the client's payment terms.","Escalation should include the history, the last action, and the specific ask. Do not send a raw portal screenshot without context. The person receiving the escalation should be able to act without reopening the whole file. A clear escalation is faster for everyone and creates a better record. Include the escalation date and the response received so the next reviewer knows what has already been tried."]},{"heading":"Review the mismatch pattern weekly","paragraphs":["At the end of the week, group the mismatches by cause and by vendor. Look for repeated rejection codes, fields that are consistently wrong, and handoffs where status stops moving. Choose one process fix for the coming week and assign it to an owner. The daily routine finds the issues, and the weekly review prevents them from recurring.","Share the pattern with the billing manager and, when useful, with the client or vendor contact. A vendor that repeatedly rejects the same field may need a mapping correction rather than more individual corrections. A client that changes its portal requirements may need a revised submission checklist. The weekly view turns daily effort into a durable improvement."]}],"faq":[{"q":"How long should the daily reconciliation take?","a":"For a typical firm queue, fifteen to thirty minutes is enough when the review is limited to records that changed since the prior check. A larger or more volatile queue may need a second daily pass. Track the time so the routine stays proportionate to the risk."},{"q":"What if the portal and billing system use different status names?","a":"Create a mapping table that defines which portal status corresponds to each internal status. Review the mapping when either system changes. Record the portal status verbatim in the reconciliation log so the original evidence is preserved."},{"q":"Who should receive the weekly pattern report?","a":"Send it to the billing manager and the e-billing queue owner, with a short note to the vendor contact when the pattern is vendor-specific. Keep the report focused on causes and fixes rather than a long list of invoices."}],"publishedAt":"2026-11-07"},{"slug":"create-a-matter-billing-contact-sheet-for-faster-escalation","title":"Create a matter billing contact sheet for faster escalation","description":"A matter-level contact sheet that records who can approve rates, resolve guideline questions, and receive billing escalations without a search through email.","category":"Matter records","readTime":"8 min read","thumbnail":"/thumbnails/november-07/create-a-matter-billing-contact-sheet-for-faster-escalation.webp","internalService":"/services/matter-record-upkeep","internalSibling":"/blog/prepare-a-billing-continuity-binder-before-planned-leave","source":{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},"sections":[{"heading":"Name the people behind each billing decision","paragraphs":["A matter record often lists the client contact and the responsible attorney, but billing decisions usually involve more people. Rate approvals may sit with a procurement manager, guideline questions with an outside counsel coordinator, and invoice disputes with an accounts payable team. The contact sheet names those roles before a question becomes urgent. It turns a scavenger hunt through email into a controlled reference.","Start from the decisions the billing team actually makes and work backward to the person who can answer each one. If a rate change needs approval, name the approver. If a guideline conflict needs a client interpretation, name the coordinator who can provide it. The sheet should follow the work, not the org chart. Review the list at matter opening so the first billing question does not trigger a search."]},{"heading":"Distinguish client contacts from firm owners","paragraphs":["Keep client contacts and firm owners in separate sections so the reviewer knows who is internal and who speaks for the client. A partner may own the relationship while a client billing coordinator owns the guideline interpretation. Mixing the two can lead an assistant to ask the wrong person or to treat an internal preference as a client instruction. The distinction protects both the relationship and the record.","For each client contact, record the organization, the role, and the scope of authority. For each firm owner, record the matter responsibility and the backup. Add the preferred channel and the time zone when the contact works across regions. These details reduce the chance that a routine question waits overnight for an answer. Add the preferred language and any accessibility note when the client has asked for a specific channel."]},{"heading":"Record authority, not just a job title","paragraphs":["A title does not tell a reviewer who can approve a write-down, change a rate, or waive a late fee. Add an authority note beside each contact that states what the person may decide and what must be escalated further. Use the same authority labels across matters so reviewers can compare. Ambiguity about authority is a common cause of held prebills.","Where authority is shared, name the primary and the alternate. If a client requires two approvals for a charge above a threshold, record that rule in the same note. The sheet should not become a delegation of professional judgment to an assistant. It simply shows where the judgment lives. State the dollar threshold that triggers a second approval when the client has set one."]},{"heading":"Keep the sheet tied to the matter record","paragraphs":["Store the contact sheet with the matter record and give it the same matter number, client name, and status. Link it from the billing system or the matter management page so a reviewer can reach it in one step. A separate document that lives only in a shared drive will fall out of date. The matter record is the natural home because it changes when the matter changes.","Define which fields must match the matter record and which may differ. The contact sheet may include a billing coordinator who is not the primary client contact, but the matter number and client entity should always agree. When the matter is transferred or closed, update the sheet in the same workflow. A mismatched sheet is worse than no sheet because it looks authoritative."]},{"heading":"Set an escalation order for common issues","paragraphs":["Write a short escalation order for the issues that occur most often, such as a disputed time entry, a rejected invoice, or a missing rate. The order should say who to contact first, what to include, and when to move to the next person. Reviewers should not have to invent a path while a deadline is approaching. A documented order also prevents the same question from going to three people at once.","Include a fallback for when the primary contact is unavailable. The fallback might be a named alternate, a shared billing mailbox, or the firm's relationship partner. State the expected response window and the point at which the reviewer escalates again. The order is a guide for routine issues, not a substitute for judgment on a sensitive matter."]},{"heading":"Update the sheet at matter milestones","paragraphs":["Review the contact sheet at matter opening, at a major staffing change, and at closing. These are the points when billing contacts most often change. Add the review to the matter checklist so it is not dependent on someone remembering. A short update at the right moment prevents weeks of misdirected email. Use the same milestones in the billing calendar so the update is not an extra task.","When a contact leaves, mark the record inactive instead of deleting it. Keep the replacement and the effective date so a historical invoice can still be explained. If the client has not named a replacement, record the gap and the temporary route. An inactive contact with a clear end date is useful evidence during a transition."]},{"heading":"Protect contact data with a clear access rule","paragraphs":["Contact sheets contain names, email addresses, phone numbers, and sometimes approval authority. Limit access to the billing and matter teams that need it, and avoid circulating the sheet as an email attachment. Store it in the controlled system with the same protections as the matter record. Review access when a team member changes roles. Name the access owner and the review interval beside the storage location.","Do not copy personal contact details into informal notes or personal devices. If a reviewer needs a quick reference, use the controlled link rather than a downloaded copy. The sheet should follow the firm's privacy and retention rules, including the rules for client confidential information. Convenience is not a reason to weaken access control. If a reviewer must travel, use the controlled mobile view rather than a downloaded copy."]},{"heading":"Test the sheet with a live escalation","paragraphs":["Pick a recent billing question and follow the sheet as if it were new. Time how long it takes to identify the right contact, find the authority note, and send a complete message. If the path required a search through email or a guess, the sheet needs a fix. A test on a real question is more revealing than a review of the fields.","Ask the person who received the test message whether it contained enough context to act. Their answer shows whether the escalation template and the authority note are working. Update the sheet and the template together, then run one more test with a different issue. The goal is a path that any trained reviewer can follow under time pressure."]}],"faq":[{"q":"Who should maintain the contact sheet?","a":"The matter owner or billing manager should own the sheet, with the billing assistant keeping routine fields current. Changes to authority should require confirmation from the firm owner. Name a backup for updates during leave."},{"q":"How much contact detail is appropriate?","a":"Record the role, organization, scope of authority, preferred channel, and time zone. Avoid personal information that is not needed for billing work. Keep the detail proportionate to the decisions the sheet supports."},{"q":"Should the sheet include client billing portals?","a":"Yes, include the portal name and the administrator contact when the client requires submissions through a portal. Note any access restrictions and the internal owner of the portal account. Do not store passwords in the sheet."}],"publishedAt":"2026-11-07"},{"slug":"prepare-a-billing-continuity-binder-before-planned-leave","title":"Prepare a billing continuity binder before planned leave","description":"A practical continuity binder that lists open billing work, decision owners, access paths, and the first actions a covering specialist should take.","category":"Role design","readTime":"8 min read","thumbnail":"/thumbnails/november-07/prepare-a-billing-continuity-binder-before-planned-leave.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/turn-write-off-patterns-into-a-monthly-coaching-agenda","source":{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},"sections":[{"heading":"Start from the work that cannot wait","paragraphs":["A continuity binder should begin with the work that will cause harm if it waits a week. That usually includes prebills nearing a release deadline, e-billing rejections with a correction window, and client questions that promise a same-day answer. List those items first rather than organizing the binder around the calendar. The covering specialist needs to know what to protect before learning the full role.","Separate work that must continue from work that can pause. A monthly report can often wait, while a daily rejection queue cannot. Write the difference down so the covering specialist does not spend the first day on low-risk tasks. The binder should make priority visible without requiring a meeting to interpret it. Write the priority order on the first page so it is visible without opening the rest of the binder."]},{"heading":"Document the queue, not every task","paragraphs":["Describe each recurring queue in a short paragraph that names its purpose, its source system, its normal volume, and its deadline pattern. Then list the steps a trained reviewer performs and the point where work must escalate. Do not reproduce every click or every report variation. The binder is a map for someone who already knows the basics, not a replacement for training.","Include the location of the current checklist and the name of the person who owns it. Note any queue that changes weekly so the covering specialist knows where to look for the latest instruction. If a queue is paused during leave, say so and name the person who authorized the pause. A binder that hides a pause looks like an oversight later."]},{"heading":"Name the temporary decision owner","paragraphs":["For every approval that normally rests with the person going on leave, name a temporary owner and the scope of that authority. Be specific about what the temporary owner may approve and what must still wait. A generic deputy label creates uncertainty and encourages informal approvals. The written scope protects the firm and gives the covering specialist a clear path.","Record the temporary owner in the systems that drive the workflow, not only in the binder. Update the approval routing, the queue assignment, and any shared mailbox rules. Tell the client contact who will handle routine questions during the leave. The binder supports the change, but the systems must reflect it. Confirm the temporary owner in writing with the practice group leader before the leave begins."]},{"heading":"Record access and system dependencies","paragraphs":["List the systems the covering specialist will use, the level of access required, and the person who can grant it. Include the billing system, the e-billing portal, the document repository, and any shared mailbox. Test the access before the leave starts so a missing permission does not become the first crisis. Note any system that requires a separate approval or device.","Describe the dependencies that are easy to miss, such as a report that runs overnight or a vendor contact who only responds by phone. Include the location of saved searches, templates, and import files. If a process depends on a person outside the team, name that person and the expected response time. The goal is to reduce the number of questions that require the person on leave."]},{"heading":"List open exceptions with their next action","paragraphs":["Create a table of open exceptions with the matter, the issue, the current status, the next action, and the due date. Include the evidence already gathered and the person who owns the next step. Sort it by due date and consequence rather than by client name. The covering specialist should be able to open the table and start working without reconstructing each item.","Distinguish an exception that needs a decision from one that needs a routine follow-up. A decision item should name the approver and the question in one sentence. A follow-up item should name the contact and the last communication date. This distinction keeps the covering specialist from escalating work that only needs a reminder. Add the date of the last client communication so the covering specialist knows what has already been said."]},{"heading":"Brief the covering specialist in person","paragraphs":["Walk through the binder with the covering specialist before the leave begins. Use a real queue and a real exception so the explanation stays concrete. Ask the specialist to repeat the priority order and the escalation path in their own words. A conversation reveals misunderstandings that a written binder cannot correct on its own. Keep the walkthrough short enough to repeat with a second reviewer if the first becomes unavailable.","Give the specialist time to ask questions and to identify gaps in the binder. The person who will cover the work often notices missing access or unclear instructions faster than the author. Record the gaps and fix them before the leave starts. The briefing is also a chance to confirm the temporary authority in writing."]},{"heading":"Run a short handover drill","paragraphs":["A drill does not need to be elaborate. Have the covering specialist handle one routine item and one exception while the regular owner observes. Check whether they can find the source, apply the checklist, and record the outcome. If they cannot complete the item, the binder or the access needs repair before the leave begins.","Keep a short record of the drill, including what worked, what was missing, and who fixed it. Use the same record to improve the next handover. A drill that is treated as a formality will not surface the real gaps. Record the drill date, the observer, and any gap that must be closed before the leave begins."]},{"heading":"Review the binder after the leave ends","paragraphs":["When the regular owner returns, review the binder with the covering specialist before the details fade. Ask which instructions were accurate, which were stale, and which questions came up repeatedly. Update the binder while the experience is fresh. The post-leave review is the most efficient way to improve the next handover. Ask the covering specialist to note any question that required a search outside the binder.","Record any decision that was made under temporary authority and confirm that the regular owner accepts it. Check that access granted for the leave is removed or adjusted. Then archive the binder version with the dates it covered. A continuity binder improves through use, and each leave should leave it stronger. Add the review date to the binder index so the next owner knows when it was last tested."]}],"faq":[{"q":"How far ahead should the binder be prepared?","a":"Start at least two weeks before a planned leave so access can be tested and gaps repaired. A shorter window is possible for an urgent absence, but the first priority is the open work and the temporary authority. Update the binder continuously between leaves."},{"q":"Who should cover billing work during leave?","a":"Choose someone who already understands the billing workflow and give them a named backup for their own tasks. Avoid assigning coverage to a person who is already at capacity. Confirm the temporary authority in writing and reflect it in the systems."},{"q":"What should the binder not include?","a":"Do not include passwords, unnecessary personal data, or a full copy of the client guideline. Link to controlled sources instead. Avoid reproducing every task step when a current checklist already exists."}],"publishedAt":"2026-11-07"},{"slug":"use-a-five-field-test-before-reopening-a-closed-invoice","title":"Use a five-field test before reopening a closed invoice","description":"A five-field decision test that keeps a closed invoice closed unless the approval record, current guideline, facts, financial effect, and owner all support a reopen.","category":"Invoice follow-up","readTime":"9 min read","thumbnail":"/thumbnails/november-07/use-a-five-field-test-before-reopening-a-closed-invoice.webp","internalService":"/services/invoice-follow-up","internalSibling":"/blog/run-a-daily-e-billing-status-reconciliation","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Why reopening is a decision, not a reflex","paragraphs":["A closed invoice is a record that the firm and the client have already acted on. Reopening it can change a payment status, a trust accounting entry, or a client's view of the bill. The decision deserves a consistent test rather than an urgent email. A five-field test slows the request just enough to prevent avoidable reversals.","The test also protects the billing team from reopening an invoice for a question that can be answered without changing the record. Many requests are really requests for an explanation, a copy, or a note. The first step is to classify the request before touching the invoice. That classification is part of the first field."]},{"heading":"Field one: the original approval record","paragraphs":["Find the approval that allowed the invoice to close. It may be a partner sign-off, a client acceptance, or a system status that records release. Read the approval in context and confirm which version of the invoice it covers. If the approval is missing or ambiguous, the reopen question may actually be an approval repair question.","Record the approver, the date, and the approval scope in the reopen note. A later reviewer should be able to see why the original close was valid at the time. Do not assume that a new question invalidates the old approval. The test asks whether the approval still supports the current record, not whether someone now has doubts."]},{"heading":"Field two: the client's current guideline","paragraphs":["Check the client guideline that applies to the invoice date, not only the guideline in force today. A rule may have changed after the work was billed, and applying the new rule retroactively can be wrong. Note the version and the effective date in the reopen note. If the guideline is ambiguous, the request may need a client interpretation before any change.","Compare the specific charge with the rule rather than the whole invoice with the whole guideline. A single line may be the only issue, and reopening the entire invoice can create unnecessary rework. If the guideline permits the charge with approval, field one and field five become more important. The fields work together rather than in isolation."]},{"heading":"Field three: the change in facts","paragraphs":["State what is actually different from the facts known at closing. A new client email, a corrected time entry, a rate change, or a missing document are different kinds of change. Write the change in one sentence and attach the evidence. If nothing has changed and the request is only a preference, the test should not support a reopen.","Distinguish new facts from newly discovered facts. A document that existed at closing but was never reviewed is a discovery issue, while a client decision made afterward is a new fact. The distinction affects who should decide and whether the original close was reasonable. Record it explicitly so the decision does not rest on memory. Name the accounting contact who will confirm the treatment before the correction is posted, and confirm that the client is notified."]},{"heading":"Field four: the financial consequence","paragraphs":["Quantify the effect of the reopen on the invoice total, the client's payment, and any downstream reporting. A small correction may not justify reopening a paid invoice, while a material error may require it even after payment. Include the cost of the rework and the risk of a duplicate credit. The number does not decide the question, but it makes the tradeoff visible.","Check whether the change affects a trust or retainer balance. A billing correction can require a corresponding adjustment that is easy to miss when the focus is only the invoice line. Name the accounting owner who must review the adjustment. If the consequence is unclear, the reopen should wait until it is understood. Record that confirmation beside the correction so the file shows who verified the client notice."]},{"heading":"Field five: the accountable approver","paragraphs":["Name the person with authority to reopen the invoice and the person who must approve the corrected version. These may be different roles. A billing manager may reopen the record while a partner must approve the new amount. Record both so the workflow does not stop halfway. The approver should see the first four fields before deciding.","If the original approver is unavailable, name the documented alternate rather than the most convenient person. The alternate should have the same scope and should record the basis for the decision. A reopen approved outside the authority path creates a control gap even when the outcome is correct. The fifth field is what keeps the decision accountable."]},{"heading":"Document the reopen and its reversal path","paragraphs":["Write a reopen note that includes the request, the five fields, the decision, and the evidence. Link the note to the original invoice and to any corrected version. State what would need to change to reverse the reopen, such as a client instruction or a corrected source record. The note should be usable months later by someone who was not involved.","Do not overwrite the original invoice without preserving the prior state. Keep a version history or a read-only copy that shows the amount and status before the change. If the reopen is later reversed, record the reversal and the reason. A clean audit trail is the difference between a controlled correction and an unexplained edit."]},{"heading":"Review reopened invoices for a pattern","paragraphs":["At the end of each month, review the invoices that were reopened and the ones that were requested but not reopened. Group them by cause, client, and billing owner. A repeated cause may point to a checklist gap, a training need, or a guideline that is being applied inconsistently. The pattern is more valuable than any single decision.","Share the pattern with the billing manager and the client relationship owner without naming individuals unnecessarily. Choose one process change and test it in the next cycle. If the reopen rate falls, the change is working. If it does not, examine whether the requests are arriving through a channel the team has not addressed. Keep the list short enough to review in the monthly billing meeting and assign one owner for follow-up."]}],"faq":[{"q":"Can an invoice be reopened after payment?","a":"Yes, but the threshold should be higher because the change affects cash and client reporting. The five-field test still applies, and the accounting owner should confirm the treatment. A small correction may be handled as a credit rather than a full reopen."},{"q":"Who should decide a reopen?","a":"The billing manager or another named owner should decide whether to reopen, and the authorized approver should approve the corrected amount. Record both decisions. Do not let the person who requested the change approve it alone."},{"q":"What if the client asks for a change verbally?","a":"Ask for the request in writing or document the call with the date, the participants, and the specific instruction. Attach that record to the reopen note. A verbal request can start the review, but the approval should be documented before the invoice changes."}],"publishedAt":"2026-11-07"},{"slug":"turn-write-off-patterns-into-a-monthly-coaching-agenda","title":"Turn write-off patterns into a monthly coaching agenda","description":"A monthly routine that groups write-off reasons, finds timekeeper patterns, and turns the evidence into one focused coaching conversation.","category":"Billing reporting","readTime":"8 min read","thumbnail":"/thumbnails/november-07/turn-write-off-patterns-into-a-monthly-coaching-agenda.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/build-a-client-billing-guideline-change-log","source":{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},"sections":[{"heading":"Separate write-offs from write-downs","paragraphs":["A write-off removes an amount that the firm has decided not to bill, while a write-down reduces a billed amount to a lower approved figure. The two have different causes and different coaching implications. Mixing them in one report hides whether the problem is poor time capture, a client guideline conflict, or an approval decision. Start the monthly review by separating the categories.","Define each category in the report notes so the numbers mean the same thing every month. Include the amount, the matter, the timekeeper, the client, and the reason code. If the reason code is missing, treat that as a data quality issue rather than assigning a guess. A clean category structure is the foundation for any useful coaching agenda."]},{"heading":"Group the reasons into a short taxonomy","paragraphs":["Use a short list of reasons that map to actions the team can take. Common groups include narrative quality, guideline compliance, rate or staffing mismatch, duplication, and client relationship concessions. Each group should have a clear definition and an example. A taxonomy with twenty reasons will be used inconsistently and will not support coaching. Test the list on last month's write-offs before the first coaching session and remove any label that did not change the action.","Review the taxonomy with the billing manager before the first report. Ask whether the groups reflect the decisions the firm actually makes. Add a category only when it changes the action a reviewer would take, and retire one when it no longer appears. Keep the definitions in the report template so a new analyst does not invent a category."]},{"heading":"Look for timekeeper-specific clusters","paragraphs":["Compare the reason mix across timekeepers with similar work and similar clients. A cluster is more meaningful when the comparison controls for matter type and client guideline. One timekeeper with several narrative write-downs may need a specific example, while a whole group with the same issue may need a template change. The comparison should inform the response, not rank people.","Be careful with small numbers. A timekeeper with two entries and one write-off can look worse than a timekeeper with fifty entries and five. Report the count and the context beside the rate. Do not use the monthly agenda to make a performance judgment that the sample cannot support. The purpose is to find a coachable behavior."]},{"heading":"Choose one behavior per coaching cycle","paragraphs":["A coaching session that covers every reason category will be remembered for none of them. Pick one behavior that is specific, observable, and connected to the month's evidence. Examples include writing an outcome in the first sentence or splitting a block entry before it reaches the prebill. Explain why the behavior matters to the client and to the review.","Choose the behavior with the largest preventable effect, not the largest raw count. A small number of high-value write-downs may matter more than many tiny corrections. Confirm the choice with the billing manager and the practice group leader. One clear focus is easier to reinforce during the next month. Write the chosen behavior and the reason for it in the session notes so the next cycle can build on it."]},{"heading":"Use redacted examples in the session","paragraphs":["Bring two or three redacted examples that show the behavior in context. Include a strong example, a weak example, and a borderline example that required judgment. Remove client names, matter numbers, and any privileged detail. The team should recognize the pattern without being able to identify the client or the timekeeper. Ask the timekeeper to explain the context before the group comments on the example.","Ask the team to apply the standard to the examples before you explain the answer. Discussion exposes where the group interprets the rule differently. Record the points of disagreement and use them to refine the standard. A coaching session that only presents conclusions misses the chance to align judgment. Keep a short record of the questions so the standard can be clarified after the session."]},{"heading":"Set a measurable follow-up","paragraphs":["Choose one measure that will show whether the coaching changed the work. It might be the share of entries with a stated outcome, the number of block entries split before review, or the count of a specific write-down reason. Keep the measure narrow and collect it the same way each month. A broad scorecard will not show whether the session had an effect.","Share the measure with the team at the next session and explain what changed. If the measure did not move, ask whether the barrier was knowledge, time, or the system. Adjust the coaching or the workflow rather than repeating the same message louder. The follow-up is what turns a monthly meeting into a learning cycle."]},{"heading":"Avoid turning coaching into blame","paragraphs":["Write-offs often involve judgment, client pressure, and incomplete information that the timekeeper did not control. A coaching agenda that ignores those conditions will produce defensiveness and hidden problems. Focus on the decision pattern and the available evidence, not on the person's worth. Ask what made the weak entry seem reasonable at the time. Separate a process barrier from a knowledge gap before deciding on an individual conversation.","Keep individual performance management separate from the group coaching session. The monthly agenda is for shared learning and process improvement. If a specific performance issue persists, address it through the firm's normal management path with the full context. Mixing the two undermines the trust the session needs. Document the management referral separately from the coaching notes and keep the group discussion general."]},{"heading":"Report the trend, not just the total","paragraphs":["Show the monthly total beside the prior months and the reason mix. A stable total can hide a shift from narrative issues to guideline issues, which calls for a different response. Add the number of matters and the billed amount so the reader can see whether the change is volume or behavior. The trend is the useful management signal.","Send the report to the billing manager and the practice group leader before the coaching session. Keep it short enough to read in five minutes and specific enough to support the chosen focus. End with the one behavior and the follow-up measure. A report that ends with a question rather than a decision will not change the next month."]}],"faq":[{"q":"How often should the coaching agenda run?","a":"Monthly works for most firms because it gives enough data to see a pattern without waiting a quarter. A firm with a small billing volume may need to combine two months. The key is a consistent cycle and a clear follow-up."},{"q":"Should individual timekeepers be named in the report?","a":"Use identifiers internally when the audience needs to act on a specific pattern, but keep the coaching session focused on the behavior. Do not circulate names more widely than necessary. Follow the firm's performance and privacy policies."},{"q":"What if the write-off reason is missing?","a":"Treat the missing reason as a data quality finding and fix the intake process. Do not guess a reason to complete the report. A short guide for selecting a reason can improve consistency in the next cycle."}],"publishedAt":"2026-11-07"}];

export const november07ResearchPosts: readonly ResearchPost[] = [{"slug":"how-many-billing-guideline-versions-does-a-matter-pass-through","title":"How many billing guideline versions does a matter pass through?","summary":"A measurement protocol for counting the billing guideline versions that apply to a matter from opening to final invoice, with version definitions and evidence rules.","cluster":"Billing guidelines","finding":"A version count is only meaningful when the protocol defines what counts as a version, which matters are in scope, and how a mid-matter effective date is assigned to billed work.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how many distinct billing guideline versions apply to a single matter between matter opening and the final invoice. The unit is the matter, and the count is the number of versions in force for at least one day of billable work. The result describes the administrative burden of tracking changes, not the quality of any client or firm. It should be reported with the observation window and the client population.","Define the scope before collecting data. Include only matters with at least one invoice and at least one guideline document in the record. State whether the count covers a single client, a practice group, or every matter opened in a period. Exclude matters that were transferred without a billing history. A broad scope without a clear denominator produces a number that cannot be compared over time."]},{"heading":"Unit of analysis","paragraphs":["The primary unit is the matter, because the burden of version tracking accumulates at the matter level. A secondary unit is the billed month, which shows how often a version change lands in the middle of a billing cycle. Report both when the data supports them. Do not mix the two units in one average.","Define a version event as the date a new guideline becomes effective for the matter, not the date the email arrived. If a client issues a clarification that does not change a rule, classify it separately and exclude it from the version count. Record the classification rule in the protocol so another analyst can reproduce the result. The unit should reflect the operating question, which is how often the team must re-read and reapply a standard."]},{"heading":"Defining a version","paragraphs":["A version is a distinct controlled document or a distinct set of effective rules for the client. A clean reissue with no substantive change is a document version but not necessarily an operating version. Count operating versions when the text changes what may be billed, who must approve it, or what evidence is required. Keep document versions in a separate column so formatting churn is visible without inflating the operating count.","Where a client maintains a base policy plus matter-specific instructions, treat the combination as the version in force for that matter. Record the base policy version and the matter instruction version separately, then assign a combined identifier. This prevents a matter from appearing to have one version when its actual review standard is a blend of two sources. The combined identifier should be stable across the analysis."]},{"heading":"Evidence standard","paragraphs":["For each version, retain the source document, its version label, its effective date, and the location where the firm stored it. Retain the communication that announced the change when the document itself does not show a date. The evidence should let a reviewer confirm that the version was in force during the billed period. A memory of a phone call is not sufficient evidence for a counted version.","If the effective date is missing, record the date the firm first applied the rule and mark the entry as inferred. Do not silently assign the email date. Keep an evidence quality field with values such as documented, inferred, or disputed. Report the share of inferred versions beside the count so the reader can judge the reliability of the result."]},{"heading":"Collection method","paragraphs":["Start with the matter record and the billing system, then trace outward to the client guideline repository. Build a list of matters in scope and a list of guideline documents with their effective dates. Join the two lists by client and matter type using a documented rule. Review the join for matters that use a client group policy rather than a single client document.","Collect the invoice dates for each matter so version changes can be placed against billed work. A guideline version that took effect after the final invoice should not be counted for that matter. A version that took effect during the matter should be counted even if the invoice covered earlier work. The timeline is what prevents an inflated or deflated count."]},{"heading":"Coding version changes","paragraphs":["For each change, code whether it was substantive, clerical, or a withdrawal of a prior rule. A substantive change alters a billing condition, an approval path, or an evidence requirement. A clerical change corrects a name, date, or formatting without changing the operating rule. A withdrawal removes a rule and should be counted because the team must stop applying it.","Have a second reviewer code a sample of changes independently and compare the results. Record disagreements and resolve them with the source text. Update the coding guide with examples from the disagreements so the next analyst applies the same standard. The guide should be short enough to use during a live review of the documents."]},{"heading":"Analysis and reporting","paragraphs":["Report the distribution of version counts, not only the average. A mean of three versions can hide a group of matters with six and another with one. Include the median, the range, and the share of matters with a version change during the final billing month. Those figures show where the tracking burden is concentrated.","Break the results down by client, practice group, and matter duration. A long matter may accumulate versions simply because it lasts longer, so report versions per year of matter life as a secondary measure. Do not compare a six-month matter with a four-year matter without that adjustment. The report should state which comparisons are descriptive and which support a process change."]},{"heading":"Limits and sources of error","paragraphs":["The count depends on the completeness of the guideline repository and the quality of effective dates. A document stored only in an email thread may be missing from the repository, which undercounts versions. A document with no effective date may be assigned to the wrong period, which misplaces a change. Report both risks and the steps taken to reduce them.","A matter can also follow a client instruction that was never written into a formal guideline. The protocol should exclude informal instructions from the version count but note their frequency, because they may explain a review behavior that the formal documents do not. Do not treat the absence of a document as proof that no instruction existed. Record the instruction as an exception and name the person who confirmed it."]},{"heading":"Retention and privacy","paragraphs":["Retain the source documents and the coding sheet for the period required by the firm's records policy. Store client guidelines in the controlled repository rather than in personal folders. Limit access to the analysts and reviewers who need the documents for the study. A version count does not require copying client confidential detail into the report.","When publishing an internal result, aggregate at a level that does not identify a client or a matter. Remove client names, matter numbers, and any quoted guideline language that could reveal a negotiation position. Keep the underlying evidence in the controlled environment. The report should be useful for process improvement without becoming a disclosure risk."]},{"heading":"Using the result","paragraphs":["Use the version count to size the change log and the reviewer communication process. A client with many mid-matter changes needs a faster notice path and a clearer mapping from change to checklist field. A client with one version may need only an annual review. The count should lead to a differentiated process, not a single policy for every client.","Pair the count with the number of preventable exceptions observed in the same matters. A high version count with a low exception rate may indicate that the current process absorbs change well. A low count with a high exception rate points to a different problem, such as an unclear summary. The two measures together are more useful than either alone."]},{"heading":"Review cadence","paragraphs":["Recalculate the version count at least twice a year, or whenever a major client guideline is reissued. Keep the prior result and the source window so the trend can be compared. A one-time count is a baseline, not a control. The review cadence should match the rate at which the client population changes. Record the protocol version and the date the rules were last updated so the next count is comparable.","Review the coding rules at the same time and update them with new examples. If the share of inferred effective dates is rising, improve the intake process before trusting the trend. Record the protocol version beside the result. A measurement that changes method without disclosure cannot be compared with its own history. Ask the billing manager whether the current change log captures the versions the study identified."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"}],"publishedAt":"2026-11-07","thumbnail":"/thumbnails/november-07/how-many-billing-guideline-versions-does-a-matter-pass-through.webp"},{"slug":"what-share-of-prebill-holds-clear-without-partner-action","title":"What share of prebill holds clear without partner action?","summary":"A protocol for measuring how many prebill holds are released by the billing team, how many need a partner decision, and how long each path takes.","cluster":"Prebill workflow","finding":"The useful measure is not the total hold count but the share that clears without a partner decision, reported with the reason, the age, and the evidence required for release.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks what share of prebill holds clear without a partner or other authorized attorney decision. The purpose is to understand how much of the hold queue is administrative and how much genuinely requires professional judgment. The unit is a hold event, not an invoice, because one invoice can carry several independent holds. The result describes the observed queue and does not evaluate any individual partner's responsiveness.","Define the observation window, the client population, and the prebill cycle. Include holds opened during the window and holds that were already open at the start, with a flag for each. Exclude draft records that were never submitted for review. A clear scope prevents the denominator from drifting as the study proceeds. Record the reason the window was chosen so a later analyst can judge whether the period was typical."]},{"heading":"Defining a hold and a release","paragraphs":["A hold is a prebill record that is complete enough for review but cannot be released until a named condition is met. A release is the recorded decision that the condition was satisfied. Do not count a status change that merely reflects a new note or a reassignment. The release must change the record's eligibility to move forward.","Classify the release authority before counting. Administrative release includes corrections the billing team is authorized to make under a written rule. Partner release includes any decision reserved to an attorney or another named approver. If a hold requires both, count the highest authority required. Record the classification rule so two reviewers do not split the same event differently."]},{"heading":"Population and sampling","paragraphs":["The population is every hold event in the window for the matters in scope. If the volume is too large to review completely, sample by hold reason and by week rather than by convenience. A sample drawn only from the busiest week will overrepresent the conditions of that week. State the sampling method and the confidence limits that apply.","For each sampled hold, collect the open date, the release date, the reason, the authority, the evidence attached, and the final action. Include holds that remain open at the end of the window and mark them as censored rather than dropping them. Dropping open holds biases the result toward fast releases. The analysis should account for the observation time available."]},{"heading":"Evidence standard","paragraphs":["A release is supported when the record contains the evidence named in the hold rule. For an administrative correction, that may be a corrected field and a note referencing the rule. For a partner decision, it may be a dated approval or a documented instruction. A verbal release without a record should be coded as undocumented and reported separately.","Retain the source of the evidence and the date it was attached. Do not infer a release from the absence of a hold later in the workflow. The record may have been reopened, merged, or removed for another reason. The evidence standard should be strict enough that an independent reviewer can confirm the release from the file."]},{"heading":"Coding the release path","paragraphs":["Code each hold by the first authority that actually resolved it, not the authority named in the initial request. A hold opened as partner review may clear administratively once the rule is clarified. That outcome is important because it shows where the initial routing was unnecessarily high. Keep both the requested and the resolving authority.","Add a code for holds that were withdrawn because the underlying charge was removed. A withdrawal is not the same as an approval, and mixing them inflates the administrative release rate. Add a separate code for holds that remain open and one for holds that were escalated beyond the original owner. The coding scheme should cover the outcomes the queue actually produces."]},{"heading":"Analysis and reporting","paragraphs":["Report the share cleared by administrative authority, the share cleared by partner authority, and the share still open at the end of the window. Include the median and the oldest age for each group. A single percentage without the age distribution hides the difference between a fast administrative fix and a slow partner backlog. Include the count of holds still open at the end of the window. Show the denominator beside every percentage so the reader can judge the base.","Break the results down by hold reason and by client. A client whose guideline requires frequent partner approval will look different from a client whose holds are mostly missing matter fields. Compare the requested authority with the resolving authority to identify routing that can be corrected. The report should show where a rule change or a clearer checklist would reduce the queue."]},{"heading":"Limits and sources of error","paragraphs":["The result depends on the accuracy of the hold reason and the completeness of the release evidence. A queue that allows free-text reasons will be harder to code consistently than one with a controlled list. A release recorded only in email may be missing from the system. Report the share of records with incomplete evidence and the effect on the estimate.","Partner availability and client deadlines can change the mix during the window. A holiday week or a major filing deadline may produce a different pattern than a normal week. Do not generalize from a short window without noting the conditions. If the window is not representative, extend it or report the result as a period-specific observation. Include the number of holds that were reopened during the window because a reopen changes the release path, and report that share beside the cleared share."]},{"heading":"Retention and privacy","paragraphs":["Keep the coded dataset in a controlled location with access limited to the study team. Remove client names and matter numbers from the working file when the analysis does not need them. Retain the linkage key separately if a later audit requires re-identification. Follow the firm's retention schedule for billing records and study notes. State the access rule in the same note so a later analyst can verify who may reopen the file.","Do not include quoted client instructions in a report that circulates beyond the billing team. Summarize the rule instead. If the result is shared with a client, aggregate across matters and remove any detail that could reveal another client's position. The measurement should improve the process without creating a new confidentiality exposure. Keep the redacted version with the report and the full version in the controlled repository."]},{"heading":"Applying the result","paragraphs":["A high administrative release share may indicate that too many holds are routed to partners by default. Review the hold rules and give the billing team clear authority for the corrections it already makes. A low administrative share may indicate that the queue is capturing genuine judgment questions, which is not necessarily a problem. The response should follow the reason mix. Record the retention period and the owner of the dataset in the study file, along with the access rules that apply to it.","Use the age data to set escalation points for the slowest reason categories. If partner holds are the bottleneck, a standing review slot may be more effective than individual reminders. If administrative holds are slow, the bottleneck may be access or training. Match the intervention to the measured path rather than to the total volume. Use role labels rather than names when the result is shared with the practice group, and remove the names before the file leaves the team."]},{"heading":"Review cadence","paragraphs":["Repeat the measurement quarterly and after any change to the hold taxonomy. Keep the protocol and the coding guide stable so the trend is comparable. If a new reason category is added, report it separately for the first period rather than blending it into an existing group. The comparison should be transparent about the change. Keep the coding guide with the result so a new analyst can repeat the classification, and assign the review to a named owner.","Share the result with the billing manager and the partner responsible for the queue. Ask whether the administrative release rules still match the firm's risk tolerance. Update the rules if the answer changes, then measure again. The cadence should follow the decisions the measure is meant to inform. Record the date of the review and the name of the owner who accepted the next action."]},{"heading":"Reporting the result to the queue owner","paragraphs":["A share without context can be read as a target, so report it beside the hold volume, the reason mix, and the observation window. The queue owner needs to know whether a change in the share reflects a new routing rule or a different mix of matters. Present the result as a description of the period, not as a score for the team. That framing keeps the conversation on the process.","Ask the queue owner which holds could be moved to administrative release without weakening the control. Test one change on a small sample before applying it across the queue. Record the change date beside the next result so the comparison is honest. The measure should support a decision about routing, not just a monthly report."]}],"sources":[{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"}],"publishedAt":"2026-11-07","thumbnail":"/thumbnails/november-07/what-share-of-prebill-holds-clear-without-partner-action.webp"},{"slug":"where-do-time-entry-narratives-fail-outside-counsel-guidelines","title":"Where do time-entry narratives fail outside counsel guidelines?","summary":"A defect-coding protocol for locating where time-entry narratives miss client outside counsel requirements, with definitions, sampling, and reporting limits.","cluster":"Time capture","finding":"Narrative failures cluster by missing component and by matter type, so a useful study codes the defect against the specific guideline requirement rather than treating every client edit as one category.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks where time-entry narratives fail the client's outside counsel guidelines. The unit is a narrative line that received a client edit, rejection, or clarifying question during the observation window. The purpose is to locate the recurring defect types so training and templates can target them. The result does not measure the quality of a timekeeper's overall work.","Scope the study to one client or a defined client group with a written narrative requirement. Include lines from matters that were billed in the window and exclude lines that were never submitted. State whether the study covers all timekeepers or a sample. A clear scope keeps the denominator consistent and makes the defect rates comparable across periods."]},{"heading":"Defining a narrative failure","paragraphs":["A failure is a client action that requires the narrative to change before the line is accepted. That includes a write-down tied to the narrative, a rejection with a narrative reason code, or a documented request for clarification. A purely internal preference from a partner is not a client failure and should be coded separately. The definition should name the evidence that qualifies.","Distinguish a missing component from an inaccurate statement. A missing outcome is a different defect from a narrative that describes work that did not occur. Inaccuracy is more serious and should be reported separately rather than folded into a general quality score. The coding scheme should preserve that distinction even when both lead to a write-down."]},{"heading":"Population and unit of analysis","paragraphs":["The population is every submitted narrative line for the in-scope matters during the window. The primary unit is the line, because a single invoice can contain both strong and weak narratives. A secondary unit is the matter, which shows whether failures concentrate in particular engagements. Report the line-level rate first and the matter-level pattern second.","Record the timekeeper, the matter type, the client guideline version, and the review outcome for each line. These fields allow the analysis to separate a template problem from a matter-specific issue. Do not aggregate lines before checking whether the mix of matter types explains the difference. A raw rate across dissimilar work can be misleading."]},{"heading":"Evidence standard","paragraphs":["Use the client's written edit, rejection notice, or documented clarification as the evidence of failure. If the client only discussed the issue verbally, record the date and the participants but mark the evidence as indirect. Do not rely on a reviewer's memory of a conversation. The standard should let a second analyst confirm the defect from the file.","Retain the original narrative and the revised narrative together. The difference between them is often the clearest evidence of the missing component. If the line was removed entirely, record the client's stated reason and the amount. A removed line without a reason should be coded as unexplained rather than assumed to be a narrative defect."]},{"heading":"Sampling and collection","paragraphs":["If the volume is manageable, review every line in the window. If not, sample by client, matter type, and timekeeper so the sample reflects the population. Draw the sample before reviewing outcomes to avoid selecting only the lines that were edited. Record the sampling frame and the inclusion rules in the study file. State the sampling frame and the date it was drawn in the study file.","Collect the guideline requirement that applies to each line before reading the client's edit. That order prevents the analyst from reverse engineering a rule to fit the outcome. Use the guideline version in force for the work date, not the version current at review. The version field is essential when a client changes its narrative requirements mid-year. Keep the sampling frame with the study file so the inclusion rule can be audited later, and record the date the frame was drawn."]},{"heading":"Coding the defect","paragraphs":["Use a short set of codes that match the guideline: missing task, missing subject, missing outcome, vague time description, block entry, duplication, and confidentiality concern. Add an other category with a required note. Each code should have a definition and an example. A code that cannot be applied consistently should be revised before the main review.","Code one primary defect per line, then list any secondary defects. The primary defect is the one the client cited or the one that most clearly prevented acceptance. Secondary defects are useful for training but should not inflate the count. Have a second reviewer code a sample and compare the results. Report the agreement rate and resolve disagreements with the guideline text."]},{"heading":"Analysis and reporting","paragraphs":["Report the defect rate per hundred lines and the share of each defect type. Include the amount of the associated write-down or adjustment when the data allows. A frequent defect with a small financial effect may be less urgent than a rare defect that removes a large charge. The report should show both frequency and consequence.","Break the results down by matter type, timekeeper group, and guideline version. Look for a defect that appears only after a guideline change or only in one practice area. Compare the pattern with the narrative standard and the training examples. The output should identify one or two specific fixes, not just a ranking of defects."]},{"heading":"Limits and sources of error","paragraphs":["Client review behavior can vary by reviewer, so an edit may reflect a preference rather than a documented requirement. Code only failures tied to a written rule or a documented clarification. Report the share of edits that could not be tied to a rule. That share is a useful signal about the clarity of the guideline and the review relationship.","The sample may overrepresent matters with unusual client attention. A client that reviews every line will produce more documented failures than a client that reviews a sample. Report the client and the review intensity beside the rate. Do not compare rates across clients without noting the difference in review practice. Report the number of lines that could not be matched to a guideline version and explain why."]},{"heading":"Retention and privacy","paragraphs":["Keep the original and revised narratives in the controlled billing environment. The study file should contain only the fields needed for coding and should remove client identifiers when possible. If the narratives contain privileged detail, limit access to the study team and follow the firm's confidentiality policy. The coding notes should not quote sensitive content unnecessarily.","When sharing results, aggregate at the matter type or practice group level. Do not include examples that could identify a client or reveal a legal strategy. Use redacted examples only after the supervising attorney approves them. The study is a process improvement tool, not a substitute for the client's own review. Use a redaction checklist before any example leaves the controlled environment."]},{"heading":"Applying the result","paragraphs":["If missing outcomes dominate, revise the narrative template and the coaching example rather than adding another general instruction. If block entries dominate, change the prebill check that allows a block to pass. If confidentiality concerns dominate, add a review step before the narrative is submitted. The fix should match the defect that the data actually shows.","Test the fix on a small sample in the next cycle and compare the defect rate with the baseline. A drop in one defect type with no increase in another is evidence that the change worked. If the rate does not move, examine whether the guideline or the client reviewer changed during the period. The result should guide the next test, not close the question."]},{"heading":"Review cadence","paragraphs":["Repeat the study quarterly while the narrative standard is being revised, then move to a semiannual cycle. Keep the coding guide and the guideline version history stable so the trend is comparable. Add new defect codes only when the guideline introduces a new requirement. Report the change in method beside the result. Write the baseline and the target beside the chosen fix so the next cycle has a comparison.","Review the findings with the billing manager and the timekeeper group that produced the sample. Ask which fix is practical in the current workflow and who will own it. Set a follow-up date before the next cycle. A measurement that does not lead to an owned action becomes another report that no one uses. Record the guideline version in force at the follow-up so a change in the source is visible."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"}],"publishedAt":"2026-11-07","thumbnail":"/thumbnails/november-07/where-do-time-entry-narratives-fail-outside-counsel-guidelines.webp"},{"slug":"how-often-do-e-billing-status-feeds-disagree-with-the-vendor-portal","title":"How often do e-billing status feeds disagree with the vendor portal?","summary":"A reconciliation study protocol for comparing e-billing status feeds with vendor portals, including field definitions, sampling, and disagreement coding.","cluster":"E-billing","finding":"Status disagreement is a measurable data quality problem, and its rate should be reported by field, vendor, and age rather than as a single overall percentage.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often the firm's e-billing status feed disagrees with the vendor portal for the same invoice at the same point in time. The unit is an invoice-day observation, because a status can agree on Monday and disagree on Wednesday. The purpose is to quantify reconciliation effort and identify the fields that drift most. The result does not assign fault to the vendor or the firm.","Scope the study to one vendor or a defined set of vendors and to invoices submitted during the window. Include invoices that are pending, accepted, rejected, adjusted, and paid. Exclude invoices that were never submitted through the portal. State the observation times so a later analyst can reproduce the comparison. Record the observer and the access method so a later audit can repeat the same observation."]},{"heading":"Defining a status feed and a portal","paragraphs":["The status feed is the automated or manual data set the firm uses to track invoice state internally. The portal is the vendor's authoritative interface for submission and payment status. Define which system is authoritative for each field before comparing. The portal usually controls submission acceptance, while the firm's accounting system controls cash application. Name the system owner who can confirm the authoritative field for each status.","Record the exact field names and allowed values in both systems. A comparison between free-text notes is not a status comparison. If the firm maps portal values into internal codes, retain the mapping table and its version. The mapping is often where a disagreement originates, so it belongs in the evidence. Keep the mapping version with the study so a later comparison uses the same definitions."]},{"heading":"Observation design","paragraphs":["Observe the same invoice at a consistent time each business day for the study window. A daily observation captures movement without requiring continuous access to the portal. If daily observation is not possible, choose a fixed interval and state it. Random observation times make the disagreement rate harder to interpret. Keep the mapping table under version control because a silent change can create a false disagreement, and record who approved the last change.","Record the portal status, the feed status, the last update time in each system, and the invoice amount. Include a note when the portal is unavailable or the feed has not refreshed. Those cases are not disagreements, but they affect the denominator. Keep an observation log with the date, time, and observer. Record the refresh interval for each system beside the field definition, and note the source of that interval."]},{"heading":"Sampling","paragraphs":["If the invoice population is large, sample by vendor, submission month, and status category. Include a minimum number from each status so the study does not overrepresent pending invoices. Draw the sample before examining disagreements. A sample selected because it looks suspicious will overstate the problem. Use the same clock and time zone for both systems so a timestamp difference is not coded as a status change.","For each sampled invoice, follow it through the entire observation window rather than observing it once. A single snapshot cannot show whether a disagreement is transient or persistent. Report both the share of invoices with at least one disagreement and the share of invoice-days with a disagreement. The two measures answer different questions. Note any planned maintenance window in the observation log before the comparison begins."]},{"heading":"Coding disagreements","paragraphs":["Code a disagreement when the two systems report different states for the same invoice at the same observation time. Distinguish a value mismatch from a timing lag. A timing lag exists when the portal changed after the feed's last refresh and the feed is expected to catch up. A value mismatch exists when both systems have processed the same event but report different states. Record the selection method and the number of invoices drawn from each stratum.","Add codes for missing data, unmapped status, and duplicate invoice records. Missing data is not a disagreement, but it affects the ability to reconcile. Keep the codes small, define each one with an example, and have a second observer code a sample. Resolve differences by returning to the portal and the feed timestamp, and state the observation window beside the result."]},{"heading":"Analysis and reporting","paragraphs":["Report the disagreement rate by field, vendor, and status category. Include the median duration of a disagreement and the share that resolved within one business day. A high rate of short lags is operationally different from a low rate of persistent mismatches. The report should separate the two before recommending a fix. Include the count of invoices behind each rate so a small sample is visible.","Show the share of invoices that required manual reconciliation and the estimated time per reconciliation. Do not invent a labor rate; use the firm's actual observed time if available and label it as an estimate. Compare the rate across vendors only when the submission volume and status mix are similar. The comparison should be transparent about those conditions."]},{"heading":"Limits and sources of error","paragraphs":["Portal availability and refresh schedules can create apparent disagreements that are really timing artifacts. The observation log should record outages and known maintenance windows. A feed that refreshes hourly will look different from one that refreshes daily. Report the refresh interval beside the rate. Include the number of observations with missing data beside the disagreement rate, and separate missing data from a true mismatch.","The study observes status, not the reason for the status. A disagreement may reflect a vendor error, a mapping problem, or an internal update that was never saved. The protocol can locate the field and the timing, but a separate review is needed to assign cause. Do not infer cause from the disagreement alone. Report the share of mismatches that remain unexplained after the cause review."]},{"heading":"Retention and privacy","paragraphs":["Store the observation log and the mapping table in a controlled location. Remove client names and matter numbers from the analysis file when they are not needed. If invoice amounts are included, aggregate them before sharing outside the billing team. Follow the firm's records policy for the retention period. Record the refresh interval and the outage history in the limitations section.","Do not capture portal screenshots that contain unrelated client data. Crop or redact to the invoice under review. Limit access to the study team and the billing manager. The purpose is a data quality study, not a broader collection of client information. Keep a separate cause review for a sample of persistent mismatches if the team needs that detail, and label it as a separate follow-up."]},{"heading":"Applying the result","paragraphs":["If one field drives most disagreements, fix the mapping or the refresh schedule before adding more manual checks. If one vendor drives the rate, review the submission integration and the vendor's status definitions. If timing lags dominate, adjust the daily reconciliation time rather than escalating individual invoices. The fix should follow the measured pattern. Name the access owner and the review interval in the study file.","Test the change on the same sample design and compare the rate with the baseline. A reduction in persistent mismatches is more valuable than a reduction in short lags, because persistent mismatches are the ones that mislead the team. Report the result to the billing manager and the vendor contact. Use a redaction rule for screenshots that includes cropping unrelated invoices."]},{"heading":"Review cadence","paragraphs":["Repeat the study after any change to the portal, the feed, or the billing system. Also repeat it quarterly during the first year of a new integration. Keep the field definitions and the mapping version with the result. A comparison across versions is only valid when the definitions are stable. Record the portal and feed version with each result so a future comparison is valid.","Review the findings with the team that performs daily reconciliation and ask which mismatch caused the most rework. Their experience can explain a pattern the data only describes. Set one process change and a follow-up date. The cadence should be tied to system changes and observed risk, not to a calendar alone. Ask the reconciliation team which mismatch created the most manual work and include that note."]},{"heading":"Reporting the result to the vendor contact","paragraphs":["Share the field-level result with the vendor contact only after the firm has confirmed the mapping and the observation method. A disagreement rate without the field definition can sound like an accusation rather than a data quality request. Include one example invoice and the exact timestamps for both systems. The vendor needs enough detail to reproduce the issue.","Ask the vendor whether the portal changed its status definitions during the window and record the answer. If the cause is on the firm side, keep the conversation internal and fix the mapping before the next review. A joint review is useful when both sides can see the same evidence. It is not a substitute for the firm's own reconciliation control."]}],"sources":[{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"NIST Cybersecurity Framework","url":"https://www.nist.gov/cyberframework"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"}],"publishedAt":"2026-11-07","thumbnail":"/thumbnails/november-07/how-often-do-e-billing-status-feeds-disagree-with-the-vendor-portal.webp"},{"slug":"what-does-a-reopened-invoice-cost-in-staff-rework","title":"What does a reopened invoice cost in staff rework?","summary":"A time-and-motion protocol for estimating the staff effort caused by reopening a closed invoice, with activity definitions, sampling, and reporting limits.","cluster":"Invoice follow-up","finding":"Rework cost is best estimated from observed staff time per reopen activity, reported with the sample size and the activities included rather than as a single firm-wide average.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how much staff time a reopened invoice consumes from the request to the final corrected record. The unit is a reopen event, and the measure is active work time rather than elapsed time. The purpose is to compare the cost of preventing a reopen with the cost of processing one. The result is an operational estimate, not a billing rate or a client charge.","Scope the study to one billing team and a defined period. Include reopens initiated by a client, a partner, or an internal review. Exclude routine status updates that do not change the invoice record. State whether the estimate covers only the billing team or also includes accounting, attorney, and client-facing time. Record the team, location, and period in the study file so the estimate is not applied outside its scope."]},{"heading":"Defining a reopen event","paragraphs":["A reopen event begins when an authorized person records a request to change a closed invoice. It ends when the corrected invoice is released or the request is formally declined. A request that is answered with an explanation but no record change is a different event and should be counted separately. The definition should match the five-field decision test the firm uses.","Record the reason, the authority, the amount, and the systems touched. A reopen that requires a credit memo, a trust adjustment, or a client portal resubmission has a different activity profile from one that changes a single line. Keep these categories separate so the average is not dominated by one complex case. Use a single event identifier so the time log and the invoice record can be joined without ambiguity."]},{"heading":"Activity definitions","paragraphs":["List the activities that consume time: reading the request, locating the original approval, checking the guideline, recalculating the invoice, updating the systems, communicating with the client, and closing the record. Define the start and end of each activity. A time study is only as good as the boundaries between activities. Keep the activity list in the order the work usually occurs so the log is easy to complete.","Include waiting time separately, but do not add it to active work time. Waiting for a partner response may be the largest elapsed cost, yet it is not staff effort. Report active time and elapsed time side by side. The distinction matters when the team is deciding whether to add a reviewer or change a rule."]},{"heading":"Sampling","paragraphs":["Sample reopen events across reason categories, amounts, and requesters. A sample of only large invoices will overstate the time per event if complexity correlates with amount. A sample of only recent events may miss a seasonal pattern. Record the sampling frame and the inclusion rules before collecting observations. Record the number of events in each stratum and the share of the population it represents.","Aim for a sample large enough to report a range rather than a single number. If the team handles few reopens, extend the window instead of lowering the evidence standard. Track events that are still open at the end of the window and report them separately. Dropping them would bias the estimate toward completed cases."]},{"heading":"Observation method","paragraphs":["Use a simple time log completed by the person doing the work, with start and stop times for each activity. Ask for a short note about interruptions and handoffs. Self-reported time is imperfect, but it is often the most practical method for knowledge work. Pair it with a sample of direct observation to check for systematic over or under reporting.","Do not ask people to reconstruct a week of work from memory. Complete the log during or immediately after the event. If that is not possible, use system timestamps for the activities they cover and mark the rest as estimated. Report the share of estimated time in the final result. Ask observers to note any interruption longer than a few minutes so the active time is not overstated."]},{"heading":"Coding and calculation","paragraphs":["Calculate active minutes per event by summing the defined activities, then report the median and the range. A mean is useful for total capacity planning, but the median better represents a typical event. Exclude outliers only when the activity log shows a documented reason, and report the exclusion rule. Report the number of events with estimated time and the reason for the estimate.","Multiply the observed time by the number of events in the period to estimate total effort. Label the result as an estimate and show the uncertainty range from the sample. Do not convert the time into a dollar cost unless the firm provides an approved labor rate and the method for applying it. The protocol measures time, not price."]},{"heading":"Analysis and reporting","paragraphs":["Report time by reason category and by activity. A reopen that spends most of its time locating the original approval points to a records problem, while one that spends time recalculating points to a rate or guideline problem. The activity breakdown is more actionable than the total. Include the number of events that required a handoff and the time spent waiting at each handoff.","Compare reopen events with the preventive check that would have caught them. If a five-minute prebill check prevents a forty-minute reopen, the case for the check is strong. If the prevention would take longer than the average reopen, the firm may choose a different control. Report both sides of that comparison. State the labor rate source and the date if the firm asks for a dollar conversion."]},{"heading":"Limits and sources of error","paragraphs":["Self-reported time can be rounded, incomplete, or influenced by the desire to look efficient. Direct observation can change behavior, so use both methods on a small overlap and report the difference. Do not present a precise number when the underlying logs are coarse. Record the observation method and the overlap sample so a range can be read beside the estimate.","The sample may not represent the full year if it covers a busy season or a system transition. Report the period and any known events that affected the workload. If the reopen rate changes after a process fix, repeat the study rather than applying the old time estimate to the new workflow. Compare the reopen period with the prior period before applying the estimate to a budget."]},{"heading":"Retention and privacy","paragraphs":["Keep the time logs and the event list in a controlled folder. Remove client names and matter numbers from the analysis file when they are not needed. If a log includes a narrative about a difficult client interaction, summarize it rather than copying it into the report. Follow the firm's records and privacy policies. Name the records owner and the retention period in the study file.","Aggregate the results before sharing beyond the billing team. Do not identify an individual's time as a performance measure without the proper management context. The study is about process cost, not individual productivity. Keep the raw logs available only to the reviewers who need them. Use role labels and aggregate time when the result is shared outside the billing team."]},{"heading":"Applying the result","paragraphs":["Use the activity breakdown to choose one prevention lever. If locating approvals dominates, improve the approval record in the matter file. If guideline checks dominate, move the check earlier in the prebill. If client communication dominates, clarify the correction window at submission, and assign the prevention fix to one owner with a date for the next measurement.","Set a target for the next period and measure both the reopen rate and the active time per event. A lower reopen rate with the same time per event is still a gain in total capacity. A stable rate with lower time per event may mean the process is getting smoother. Report both so the improvement is visible."]},{"heading":"Review cadence","paragraphs":["Repeat the time study annually or after a major system change. Keep the activity definitions stable so the comparison is meaningful. If a new step is added, report its time separately for the first period. Do not blend a new activity into an old category without disclosure. Record the activity definitions with the result so a later study uses the same boundaries.","Review the result with the billing manager, the accounting owner, and a reviewer who handles reopens. Ask whether the observed activities match the real workflow and whether any step is missing. Update the protocol before the next round. A cost estimate that no one who does the work recognizes will not be trusted. Ask the reviewers whether the log captured the real work or only the steps they remembered."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-07","thumbnail":"/thumbnails/november-07/what-does-a-reopened-invoice-cost-in-staff-rework.webp"},{"slug":"how-much-do-billing-contacts-change-during-a-matter-lifecycle","title":"How much do billing contacts change during a matter lifecycle?","summary":"A contact-churn protocol that counts billing role changes from matter opening to close and reports their effect on escalation and approval paths.","cluster":"Matter records","finding":"Contact churn is a measurable record quality issue, and its effect depends on which role changed, whether a replacement was named, and how long the gap lasted.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often the billing contacts on a matter change between opening and closing. The unit is a role change event, not a person, because a matter can have several billing roles with different stability. The purpose is to understand how often the escalation path depends on an outdated record. The result describes the record, not the performance of any individual contact.","Scope the study to matters opened and closed within a defined period, or to open matters observed for the same length of time. Include client billing contacts, firm billing owners, and approvers named in the matter record. Exclude contacts who were never assigned a billing role. State the observation window and the matter types included."]},{"heading":"Defining a contact change","paragraphs":["A contact change occurs when the person or role named for a billing function changes, or when a named contact leaves and no replacement is recorded. Distinguish a substitution from a reassignment: a substitution keeps the same role and authority, while a reassignment changes the scope. Both affect the record, but they have different implications for approval. Report the two event types separately so the churn rate does not combine a name change with a scope change.","Count a change only when the matter record or the controlled contact sheet is updated or should have been updated. A new name in an email signature is not a record change. The evidence standard should require a dated source. A change that is known only through conversation should be coded as undocumented. Record the authority level with each role so a contact change can be separated from an authority change."]},{"heading":"Roles to track","paragraphs":["Track the roles that actually appear in the billing workflow: client billing coordinator, client accounts payable contact, firm billing owner, responsible attorney, rate approver, and guideline interpreter. Some matters will not have every role. Record whether the role was absent, unfilled, or filled by a named person. Absence is different from churn and should not be counted as a change.","Define the authority attached to each role at the start of the study. If the authority changes without a person change, record that as a separate authority event. A new coordinator with the same approval limit is a contact change, while the same coordinator with a new limit is an authority change. Keeping them separate makes the analysis more useful."]},{"heading":"Evidence and collection","paragraphs":["Use the matter record, the contact sheet, and the client's written notices as the primary sources. Record the effective date of each change and the date the firm updated its record. The gap between the two is a useful measure of record lag. If the change was never recorded, mark it as a missing update rather than dropping it.","Collect the data at matter opening and at defined milestones, such as a major staffing change, a rate review, or closing. A single end-of-matter review may miss changes that were corrected before closing. The milestone approach captures the state the reviewer actually saw. Keep the collection dates so the timeline is clear. Note the source of the update, such as a client notice or a system change, beside the effective date."]},{"heading":"Measuring churn","paragraphs":["Calculate the number of role changes per matter and the share of matters with at least one change. Report the median time between changes and the share of changes with a gap before the record was updated. A simple count without the timing does not show the operational effect. Report the number of matters with no contact change as well as the number with several.","Compare churn by matter duration, client, and matter type. Longer matters have more opportunity for change, so report changes per year as a secondary measure. A high-churn client may need a standing contact review, while a low-churn client may need only a closing check. The comparison should be descriptive, not a rating of the client relationship."]},{"heading":"Analysis and reporting","paragraphs":["Report the roles with the highest change rate and the roles with the longest update lag. A frequently changing coordinator role may need a shared mailbox rather than a named person. A slow-updating approver role may need a system prompt at the point of prebill release. The role-level view points to a specific control. Include the share of matters where the record was updated after a billing question had already occurred.","Show the share of matters where the recorded contact was wrong at the time of a billing question. This is the operational consequence measure, and it may be more persuasive than the raw churn rate. If the study cannot observe actual questions, report the share of records that were stale at a milestone instead. Label the measure accurately."]},{"heading":"Limits and sources of error","paragraphs":["The matter record may be incomplete, especially for client-side contacts who are not regular correspondents. A missing contact is not proof that no contact existed. Report the completeness of the source before drawing conclusions. A study based only on the firm's record may undercount client changes. Name the owner of each contact update and the system where the change is recorded.","Matter duration and client size can confound the comparison. A large client with a procurement function may change contacts more often than a small client with a single relationship partner. Report the context beside the rate and avoid ranking clients on churn alone. The purpose is to improve the record, not to evaluate the client."]},{"heading":"Retention and privacy","paragraphs":["Store the contact history in the controlled matter record and keep the study file separate from the live sheet. Remove personal contact details from the analysis file. If a report includes a role change, use the role rather than the person's name. Follow the firm's privacy policy for client and employee data. Record the matter duration and the number of billing cycles observed for each matter.","Do not circulate a list of departed contacts outside the team that needs it for continuity. Keep the historical record available for billing questions but restrict access. A contact history is useful evidence and also sensitive personal information. Handle it with the same care as the matter record. Record the access rule that governs the historical list in the same note."]},{"heading":"Applying the result","paragraphs":["If client-side roles change often, add a shared billing mailbox and a named firm owner who maintains the relationship. If firm-side roles change, add the contact review to the matter transition checklist. If the update lag is the main problem, trigger a review at the milestones where changes are known to occur. The response should match the role and the timing. State the completeness rate of the matter record beside the churn result.","Test the change by measuring the share of stale records at the next milestone. A drop in stale records is the direct result; a drop in escalations sent to the wrong person is the operational result. Report both if the data allows. The study should improve the escalation path, not just describe it. Use role labels in the group report and keep names in the controlled study file, then remove the names from any shared extract."]},{"heading":"Review cadence","paragraphs":["Repeat the study annually and after a major client or firm reorganization. Keep the role definitions stable so the comparison is valid. If a new role is added, report it separately for the first period. A churn measure that changes its categories every cycle cannot show a trend. Record the role definitions with the result so a later study uses the same categories.","Review the findings with the billing manager and the matter administration lead. Ask which role causes the most rework and which update trigger is easiest to add. Set one change and a follow-up date. The cadence should be tied to the operating decisions the measure supports. Write the next review date in the matter team's calendar before the meeting ends."]},{"heading":"Reporting the result to the matter team","paragraphs":["Present the role-level result to the matter team with the update lag and the stale-record share beside the churn count. The team needs to see which role causes the most rework, not just how many contacts changed. Use role labels in the group view and keep names in the controlled file. A short table is easier to act on than a long narrative.","Ask the team which milestone would have caught the most changes and add that trigger to the matter checklist. Test the trigger on the next group of matters and compare the stale-record share. Record the change and the owner in the study file. The result should improve the escalation path in a way the team can verify."]}],"sources":[{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"NIST Cybersecurity Framework","url":"https://www.nist.gov/cyberframework"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"}],"publishedAt":"2026-11-07","thumbnail":"/thumbnails/november-07/how-much-do-billing-contacts-change-during-a-matter-lifecycle.webp"},{"slug":"how-complete-are-billing-continuity-binders-across-a-practice-group","title":"How complete are billing continuity binders across a practice group?","summary":"A completeness audit protocol for billing continuity binders, with required elements, scoring rules, sampling, and limits for a practice group review.","cluster":"Role design","finding":"Binder completeness should be scored against a fixed element list and reported with the missing elements, because a single percentage hides whether the gap is access, authority, or open work.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how complete the billing continuity binders are across a practice group. The unit is a binder for one billing role or one queue, not a person. The purpose is to find the elements that are missing before a planned or unplanned absence creates a service gap. The result is a readiness assessment, not a performance review.","Scope the audit to the roles and queues that handle billing work in the practice group. Include binders for primary owners and for backups when a separate binder exists. State whether the audit covers prebill, e-billing, invoice follow-up, and reporting, or only a subset. A clear scope prevents the group from appearing complete because an important queue was omitted."]},{"heading":"Required elements","paragraphs":["Define a fixed list of required elements before reviewing any binder. A useful list includes the queue purpose, the source systems, current access paths, the temporary decision owner, open exceptions with next actions, the escalation order, and the location of the current checklist. Add the review date and the owner of the binder. Each element should be observable in the document.","Keep the list short enough to score consistently. If an element is important but rarely applicable, mark it as conditional rather than required. For example, a client portal access note may be conditional for a role that never submits through a portal. The scoring guide should state how conditional elements affect the result. Record the binder owner and the last update date in the audit file for each role."]},{"heading":"Scoring rules","paragraphs":["Score each element as present, partial, or missing. Present means the binder contains the specific information and a reviewer could act on it. Partial means the element is mentioned but lacks a name, date, link, or actionable step. Missing means the element is absent or unusable. Define the difference with examples so two reviewers score the same binder similarly.","Calculate a completeness score for each binder and for the practice group. Report the element-level results beside the total, because a group can score well overall while missing the same critical element in every binder. Weight the elements only if the practice group has an explicit reason to do so. Otherwise, keep the score unweighted and transparent."]},{"heading":"Sampling","paragraphs":["Audit every binder in scope when the number is small. If the group has many similar queues, sample across role type, location, and queue volume. Include at least one binder from each queue type so a missing category is visible. Do not sample only the binders that are known to be well maintained. Report the conditional elements separately so a missing portal note does not lower a role that never uses one.","Review the binder version that would be used in an absence, not an older draft in a shared folder. Record the version date and the location. If there are multiple copies, score the one the covering specialist would actually open. The audit should reflect the real handover path. Keep the scoring examples with the audit so a new reviewer applies the same standard."]},{"heading":"Evidence and verification","paragraphs":["Read the binder and then test two elements against the live systems. Confirm that the listed access path works and that the named temporary owner is recorded in the approval routing. A binder can look complete while the system still points to the person on leave. The verification step is what separates a document review from a readiness check.","For open exceptions, confirm that the next action and due date are current. A stale exception list can be more dangerous than no list because it implies work is handled. Record the date of the last update and compare it with the review date. Note any element that could not be verified within the audit window."]},{"heading":"Coding gaps","paragraphs":["Group gaps into access, authority, open work, contacts, and process documentation. Access gaps mean the covering specialist cannot enter a system, while authority gaps mean no one is named to make a decision. Open work gaps mean the binder does not show what must continue, and contact gaps mean the escalation path is incomplete. Process gaps mean the steps are missing or unclear, so record the owner and the target date for each one.","Use one primary gap category per missing element and list secondary categories when needed. The primary category should point to the fix owner. For example, an access gap belongs to the system administrator, while an authority gap belongs to the practice group leader. The coding should make the remediation path obvious. Record the owner and the target date beside each primary gap in the audit file."]},{"heading":"Analysis and reporting","paragraphs":["Report the completeness score by binder, the share of binders missing each required element, and the number of critical gaps. A critical gap is one that would stop the covering specialist from releasing a prebill or responding to a client. Show the critical gaps first, even when the overall score is high. Assign each primary gap to the role that can close it and set a target date.","Break the results down by queue type and by role. A group may have strong prebill binders and weak e-billing binders, which calls for a targeted fix. Include the date of the last binder update. A recently updated binder with missing elements is a different problem from an old binder that was never maintained. Include the number of critical gaps by queue type so the practice group can sequence the work."]},{"heading":"Limits and sources of error","paragraphs":["The audit measures the document and a sample of live paths, not the covering specialist's actual ability. A complete binder can still fail if the person lacks training or if the systems change during the absence. Report the audit as one part of readiness. Pair it with a handover drill when possible. State the audit date and the binder version beside each score.","A binder may be intentionally concise because the covering specialist already knows the workflow. The required element list should still apply, but the evidence can be a link to a current checklist rather than a full explanation. Do not penalize concision when the path to the information is clear and tested. Pair the score with the result of a handover drill when one is available."]},{"heading":"Retention and privacy","paragraphs":["Store the audit results with the practice group's continuity records. Remove personal contact details and client identifiers from the scoring sheet. If a gap involves a named individual, report the role rather than the person in the group summary. Follow the firm's retention policy for the underlying binder. Name the records owner and the retention period for the audit file.","Limit access to the binders themselves to the people who need them for coverage. An audit does not require copying the full binder into a report. Use the element-level result and a short description of the gap. The report should improve readiness without widening access to sensitive operating detail. Use role labels in the summary and keep names in the controlled audit file."]},{"heading":"Applying the result","paragraphs":["Fix critical gaps before the next planned absence, starting with access and authority. Assign each gap to the owner who can close it and set a date. A process gap may need a short writing session, while an access gap may need a system request. Do not treat every gap as a training issue. Record the fix date and re-score the same element to confirm the gap is closed.","Run a handover drill on the weakest binder and record what the covering specialist could not do. The drill tests the document and the live path together. Update the binder with the findings and re-score it. A group that closes the critical gaps and tests the result is better prepared than one with a high score and no drill."]},{"heading":"Review cadence","paragraphs":["Audit the binders before each major leave cycle, at least twice a year. Repeat the audit after a system change or a reorganization that moves billing roles. Keep the required element list stable so the scores are comparable. Add a new element only when the group agrees it is required for coverage. Record the element list version with the result so a later audit is comparable.","Review the results with the practice group leader and the billing manager. Ask which gap would cause the most harm and which fix is feasible this quarter. Set one priority and a follow-up date. The cadence should be tied to the leave calendar and the operating risk, not to an arbitrary annual review. Ask the practice group leader which gap would cause the greatest client impact and start there."]}],"sources":[{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"NIST Cybersecurity Framework","url":"https://www.nist.gov/cyberframework"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-07","thumbnail":"/thumbnails/november-07/how-complete-are-billing-continuity-binders-across-a-practice-group.webp"}];
